/**
 * App comparison data for the "best apps" pages (/best-apps and its children).
 * Checked by hand on 11 Nov 2026 against each app's live App Store page (US storefront),
 * the iTunes lookup API (US and India ratings) and Google Play. Raw notes and every source:
 * marketing/app-comparison-research-2026-11-11.md. Update both together.
 *
 * Feature marks: yes = stated by the developer (store page or site); part = partly, see note;
 * no = the developer says it is absent; ns = not stated anywhere we checked (never a guess).
 */

export type Mark = 'yes' | 'part' | 'no' | 'ns'
export type Feature = { v: Mark; note?: string }
export type FeatureKey = 'sanskrit' | 'translit' | 'meanings' | 'commentary' | 'audio' | 'offline' | 'widgets' | 'watch' | 'plans'
export type AndroidStatus = 'yes' | 'new' | 'no'

export type CompareApp = {
  key: string
  name: string
  /** The name exactly as the App Store shows it. */
  storeName: string
  developer: string
  /** One line: what the app is. */
  kind: string
  appStoreId: string
  appStoreUrl: string
  android: { status: AndroidStatus; url?: string; note?: string }
  /** Price in the US store, in words. */
  price: string
  /** The same, short, for tables. */
  priceShort: string
  ratingUS: { avg: number; count: number }
  ratingIN: { avg: number; count: number }
  /** Last version date on the App Store (YYYY-MM-DD). */
  updated: string
  /** No App Store update for over 12 months before the check date. */
  stale: boolean
  /** Apple's privacy label, strongest category shown. */
  privacy: string
  languages: string
  ads: string
  account: string
  features: Partial<Record<FeatureKey, Feature>>
  widget?: { home: Mark; lock: Mark; shows: string }
  youll: string[]
  worth: string[]
  sources: { label: string; url: string }[]
  isWisdom?: boolean
}

export const CHECKED_ISO = '2026-11-11'
export const CHECKED_LABEL = '11 Nov 2026'

